"""Responsive, ingress-compatible Guardian timeline page."""

from __future__ import annotations

from html import escape


def render_timeline_html(*, configuration_path: str, maintenance_path: str,
                         history_path: str = "history") -> str:
    return fr'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Guardian Verlauf</title>
<style>:root{{color-scheme:light dark;--blue:#0d47a1;--line:#78909c;--card:var(--card-background-color,#fff)}}*{{box-sizing:border-box}}body{{font:14px system-ui;margin:0;background:var(--primary-background-color,#f6f7f9);color:var(--primary-text-color,#222)}}header{{padding:18px 22px;background:var(--blue);color:#fff}}nav{{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}}nav a{{color:#fff;text-decoration:none;padding:8px 12px;border:1px solid #ffffff66;border-radius:8px}}nav a.active{{background:#fff;color:var(--blue)}}main{{max-width:1050px;margin:auto;padding:16px}}.panel{{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 1px 4px #0002}}form{{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));gap:10px;align-items:end}}label{{display:grid;gap:4px}}input,select,button{{font:inherit;padding:9px;border:1px solid #8888;border-radius:8px;background:transparent;color:inherit;min-width:0}}button{{cursor:pointer}}button.primary{{background:#1976d2;color:white;border:0}}.timeline{{margin-top:18px;position:relative}}.timeline:before{{content:'';position:absolute;left:118px;top:0;bottom:0;width:2px;background:var(--line)}}.event{{display:grid;grid-template-columns:100px 20px minmax(0,1fr);gap:8px;margin:0 0 14px}}.time{{text-align:right;font-variant-numeric:tabular-nums;color:var(--secondary-text-color,#555)}}.dot{{width:14px;height:14px;border-radius:50%;margin-top:5px;background:#607d8b;z-index:1}}.event.maintenance .dot{{background:#1976d2}}.event.alarm_started .dot{{background:#d32f2f}}.event.alarm_cleared .dot{{background:#388e3c}}.card{{background:var(--card);padding:12px;border-radius:10px;box-shadow:0 1px 4px #0002;min-width:0}}.kind{{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.04em}}.title{{font-weight:700;margin:3px 0;overflow-wrap:anywhere}}.summary,.meta{{overflow-wrap:anywhere}}.meta{{font-size:12px;opacity:.72;margin-top:6px}}.card a{{display:inline-block;margin-top:8px}}#message{{margin:10px 0}}.error{{padding:10px;border-left:4px solid #d32f2f;background:#d32f2f18}}@media(max-width:760px){{form{{grid-template-columns:repeat(2,minmax(0,1fr))}}}}@media(max-width:520px){{main{{padding:10px}}form{{grid-template-columns:1fr}}.timeline:before{{left:8px}}.event{{grid-template-columns:18px minmax(0,1fr)}}.time{{grid-column:2;text-align:left}}.dot{{grid-column:1;grid-row:1/3}}.card{{grid-column:2}}}}</style></head>
<body><header><h1>Guardian Battery</h1><div>Chronologischer Verlauf vorhandener Guardian-Ereignisquellen</div><nav><a href="./">Module &amp; Stack</a><a href="{escape(configuration_path, quote=True)}">Konfiguration</a><a href="{escape(maintenance_path, quote=True)}">Maintenance-Logbuch</a><a class="active" href="timeline">Verlauf</a><a href="{escape(history_path, quote=True)}">Zeitverläufe</a></nav></header><main>
<section class="panel"><h2>Verlauf</h2><p>Zeitliche Korrelation vorhandener Ereignisse; daraus wird keine Kausalität abgeleitet.</p><form id="filters">
<label>Von <input id="from" type="datetime-local"></label><label>Bis <input id="to" type="datetime-local"></label>
<label>Ereignisarten <select id="event-types" multiple size="4"><option value="maintenance" selected>Maintenance</option><option value="alarm_started">Alarm begonnen</option><option value="alarm_cleared">Alarm beendet</option><option value="status_changed">Status geändert</option></select></label>
<label>Maintenance-Kategorie <input id="category" placeholder="z. B. inspection"></label>
<label>Modul <select id="module"><option value="">Alle</option></select></label><label>Zelle <select id="cell"><option value="">Alle</option></select></label>
<label>Archiv <select id="archived"><option value="false">Archivierte ausblenden</option><option value="true">Archivierte anzeigen</option></select></label>
<button class="primary" type="submit">Filter anwenden</button></form></section><div id="message" role="status"></div><div id="timeline" class="timeline"></div>
<script>window.guardianInitialSearch=location.search;window.guardianReturnScroll=(/scroll=(\d+)/.exec(location.hash)||[])[1];(()=>{{const q=new URLSearchParams(location.search),local=v=>{{const d=new Date(v),p=n=>String(n).padStart(2,'0');return `${{d.getFullYear()}}-${{p(d.getMonth()+1)}}-${{p(d.getDate())}}T${{p(d.getHours())}}:${{p(d.getMinutes())}}`}};for(const id of ['from','to'])if(q.has(id))document.getElementById(id).value=local(q.get(id));if(window.guardianReturnScroll)setTimeout(()=>scrollTo(0,Number(window.guardianReturnScroll)),200);}})();</script>
<script>const byId=id=>document.getElementById(id);function zone(){{return Intl.DateTimeFormat().resolvedOptions().timeZone||'lokale Browser-Zeitzone'}}function localToUtc(v){{if(!v)return null;const m=/^([0-9]{{4}})-([0-9]{{2}})-([0-9]{{2}})T([0-9]{{2}}):([0-9]{{2}})$/.exec(v);if(!m)throw Error('Ungültiger lokaler Zeitpunkt.');const p=m.slice(1).map(Number),d=new Date(p[0],p[1]-1,p[2],p[3],p[4]);if(d.getFullYear()!=p[0]||d.getMonth()!=p[1]-1||d.getDate()!=p[2]||d.getHours()!=p[3]||d.getMinutes()!=p[4])throw Error('Diese lokale Uhrzeit existiert wegen einer Zeitumstellung nicht.');return d.toISOString()}}function fmt(v){{return new Intl.DateTimeFormat('de-DE',{{dateStyle:'medium',timeStyle:'short'}}).format(new Date(v))}}function optionRange(id,max){{for(let n=1;n<=max;n++){{const o=document.createElement('option');o.value=String(n);o.textContent=String(n);byId(id).append(o)}}}}function query(){{const q=new URLSearchParams(),types=[...byId('event-types').selectedOptions].map(o=>o.value);if(types.length)q.set('event_type',types.join(','));for(const [id,key] of [['category','category'],['module','module_number'],['cell','cell_number'],['archived','include_archived']])if(byId(id).value)q.set(key,byId(id).value);if(byId('from').value)q.set('from',localToUtc(byId('from').value));if(byId('to').value)q.set('to',localToUtc(byId('to').value));return q}}function restore(){{const q=new URLSearchParams(location.search);for(const [id,key] of [['category','category'],['module','module_number'],['cell','cell_number'],['archived','include_archived']])if(q.has(key))byId(id).value=q.get(key);const types=q.get('event_type');if(types)for(const option of byId('event-types').options)option.selected=types.split(',').includes(option.value);}}function kindLabel(e){{return {{maintenance:'Maintenance',alarm_started:'Alarm begonnen',alarm_cleared:'Alarm beendet',status_changed:'Status geändert'}}[e.event_type]||e.event_type}}function render(events){{const root=byId('timeline');root.replaceChildren();if(!events.length){{const p=document.createElement('p');p.textContent='Keine Ereignisse in diesem Zeitfenster.';root.append(p);return}}for(const e of events){{const row=document.createElement('article');row.className='event '+e.event_type;const time=document.createElement('time');time.className='time';time.dateTime=e.timestamp;time.textContent=fmt(e.timestamp);const dot=document.createElement('span');dot.className='dot';const card=document.createElement('div');card.className='card';const kind=document.createElement('div');kind.className='kind';kind.textContent=kindLabel(e);const title=document.createElement('div');title.className='title';title.textContent=e.title;const summary=document.createElement('div');summary.className='summary';summary.textContent=e.summary||'';const meta=document.createElement('div');meta.className='meta';meta.textContent=[e.metadata?.category,e.module_number?'Position '+e.module_number:null,e.module_number?'Seriennummer '+(e.module_serial||'unbekannt'):null,e.cell_number?'Zelle '+e.cell_number:null,e.status].filter(Boolean).join(' · ');card.append(kind,title,summary,meta);if(e.deep_link){{const a=document.createElement('a');a.href=e.deep_link;a.textContent='Maintenance-Eintrag öffnen';a.onclick=()=>{{const stateQuery=query();history.replaceState(null,'',location.pathname+'?'+stateQuery);a.href=e.deep_link+'&return='+encodeURIComponent(location.pathname+'?'+stateQuery+'#scroll='+Math.round(scrollY));}};card.append(a)}}row.append(time,dot,card);root.append(row)}}}}async function load(event){{event?.preventDefault();byId('message').replaceChildren();const stateQuery=query();history.replaceState(null,'',location.pathname+'?'+stateQuery);try{{const response=await fetch('api/timeline?'+stateQuery);const data=await response.json();if(!response.ok)throw Error(data.error?.message||'Timeline nicht verfügbar');render(data.events);const match=/scroll=(\d+)/.exec(location.hash);if(match)scrollTo(0,Number(match[1]));}}catch(error){{const box=document.createElement('div');box.className='error';box.textContent=error.message;byId('message').append(box);byId('timeline').replaceChildren()}}}}optionRange('module',6);optionRange('cell',15);restore();byId('filters').onsubmit=load;load();</script></main></body></html>'''
